extensionAttribute.scriptContentsMac:
#!/bin/zsh
# Updated by SecurityShrimp 2026 # OpenSSL Version Extension Attribute # Targets macOS 12 through 26 (Tahoe), Intel and Apple Silicon # /usr/bin/openssl is LibreSSL on every modern macOS (Apple replaced # OpenSSL years ago). Reports the LibreSSL version it identifies as, # which differs from upstream OpenSSL release numbering.
if /usr/bin/openssl version &>/dev/null; then info=$(/usr/bin/openssl version 2>/dev/null) version=$(echo "$info" | /usr/bin/awk '{print $2}') echo "<result>${version}</result>" else echo "<result>Unknown</result>" fi
